from h import *
REC_BOLETO = ("En un boleto que ya conoces bien: corte limpio por la base con navaja. Si es la primera vez que lo ves, sácalo entero, con la base del pie, "
              "para comprobar el retículo, el color de los poros y si azulea al cortarlo; luego tapa el hueco con tierra. Deja los pasados (poros verdes): "
              "La Rioja avisa de que suelen estar parasitados. Tamaño mínimo que recomienda: sombrero de 5 cm.")

nueva('boletus-aereus', cient='Boletus aereus', sin=['Boletus mamorensis (poblaciones norteafricanas, hoy la misma especie)'], es=['hongo negro'],
  eu=['onddobeltz', 'onddo beltz', 'onddo burubeltz'], grupo='boleto', clase='sin_datos', cand=True,
  clave='Boleto de sombrero pardo oscuro, casi negro y aterciopelado; poros blancos que amarillean y carne blanca. Si los poros son rojos o la carne se pone azul, no es esta.',
  mirar=[q('sombrero', 'Pardo oscuro, aterciopelado', 'Hemisférico a convexo, normalmente de 15–20 cm (puede llegar a 40). Pardo oscuro de joven; luego gris-pardo o pardo violáceo, a menudo con manchas cobrizas, doradas u oliváceas.'),
         q('himenio', 'Poros blancos → amarillo verdoso', 'Poros pequeños y redondos: blancos de joven, amarillentos o verde-amarillentos al madurar. Pueden tomar color vino al golpearlos.'),
         q('pie', 'Pie robusto con retículo', '5–15 cm, más corto que el ancho del sombrero. Con forma de barril de joven y de maza después; blanco que pasa a pardo, con un retículo del mismo color o pardo.'),
         q('carne', 'Blanca y con olor a avellana', 'Gruesa y blanca. Olor intenso y agradable que recuerda a la avellana; sabor suave y dulce.'),
         q('habitat', 'Frondosas', 'Robledales y encinares; el alcornoque es un hospedante clave. Verano y otoño.')],
  conf=[c('boletus-reticulatus', 'Boletus reticulatus', 'Muy parecido y también bajo frondosas en verano. B. reticulatus tiene el sombrero más pálido y a menudo agrietado, y un pie más claro con un retículo blanquecino más marcado, que suele llegar hasta la base.'),
        c('boletus-pinophilus', 'Boletus pinophilus', 'Crece bajo coníferas, sobre todo pino silvestre, y tiene el sombrero pardo rojizo.'),
        c('tylopilus-felleus', 'Tylopilus felleus', 'Poros rosados, retículo oscuro en el pie y sabor amargo. Es la confusión clásica de la familia del hongo.', 'media')],
  hab=['robledal', 'encinar', 'frondosas'], habt='Bosques de frondosas: robledales y encinares (Wikipedia en euskera), con el alcornoque como árbol asociado clave. Es una seta de climas cálidos: en el norte frío es rara.',
  rec=dict(acc='cortar', txt=REC_BOLETO),
  cur=['«aereus» es latín y significa «de bronce o cobre»: así se llama por el color del sombrero. La describió en 1789 el micólogo francés Pierre Bulliard.',
       'En la zona italiana de Borgotaro (Parma) B. aereus, B. edulis, B. reticulatus y B. pinophilus se recolectan y exportan desde hace siglos bajo el nombre común «Fungo di Borgotaro».',
       'En el sur de Europa mucha gente la considera mejor que B. edulis en la cocina (opinión que recoge Wikipedia, no un dato medible). En España es una de las setas silvestres que más se recogen para la mesa y también es muy popular en Navarra, el País Vasco, Francia y Grecia.',
       'Unas poblaciones del norte de África se clasificaron como otra especie (B. mamorensis); los análisis genéticos demostraron que es la misma.'],
  esp=None, meses=[6, 7, 8, 9, 10, 11], mnota='Verano y otoño.', wp=['boletus-aereus'], rioja=True)

nueva('boletus-pinophilus', cient='Boletus pinophilus', sin=['Boletus pinicola', 'Boletus edulis var. pinicola'], es=['boleto pinícola'],
  eu=['onddo pinu', 'onddo beltz kaskagorri', 'onddo gorria', 'onddo beltz kaskabeltz'], grupo='boleto', clase='sin_datos', cand=True,
  clave='Hongo de pinar: sombrero pardo rojizo (castaño), pie con retículo grueso y poros blancos que amarillean. Sin poros rojos ni carne que azulee.',
  mirar=[q('sombrero', 'Pardo rojizo, mate', 'Seco, mate, de granate a chocolate con un tinte rojizo; más grueso que en otros boletos del grupo. De joven puede ser rosa pálido con un velo blanco y polvoriento. Hasta 40 cm.'),
         q('himenio', 'Poros blancos → oliva', 'Pequeños, blancos al principio, amarillos con la edad y pardo-oliva al final. No azulean.'),
         q('pie', 'Pie abultado con retículo grueso', 'Muchas veces hinchado; el retículo es mucho más grueso que en los otros boletos parecidos. Puede tener un tinte naranja-rojizo, sobre todo abajo.'),
         q('carne', 'Blanca y no cambia', 'Blanca, blanda en ejemplares maduros, no cambia de color al golpearla. Olor y sabor agradables.'),
         q('esporada', 'Esporada pardo oliva', 'Esporas cilíndrico-elípticas que dan una esporada pardo oliva.'),
         q('habitat', 'Bajo pinos y abetos', 'Con pino silvestre, pino negro, pino marítimo, abeto y pícea. Prefiere suelos pobres, ácidos y arenosos.')],
  conf=[c('boletus-edulis', 'Boletus edulis', 'Se confunde con facilidad por el parecido de hábitat y aspecto. El sombrero de B. pinophilus es más rojizo y su retículo más grueso.'),
        c('boletus-aereus', 'Boletus aereus', 'Crece bajo frondosas, no bajo coníferas, y tiene el sombrero pardo muy oscuro.'),
        c('tylopilus-felleus', 'Tylopilus felleus', 'Poros rosados, retículo oscuro, amargo.', 'media')],
  hab=['pinar', 'abetal', 'hayedo'], habt='Ligado a pinos (silvestre, negro, marítimo, de Monterrey…) y también a abeto y pícea, en suelos pobres, ácidos y arenosos. En España aparece sobre todo en pinares viejos de pino silvestre y a veces en hayedos (Wikipedia en español).',
  rec=dict(acc='cortar', txt=REC_BOLETO), esp='pardo oliva',
  cur=['Durante años se consideró una forma del hongo común (B. edulis); el nombre B. edulis var. pinicola lo puso Carlo Vittadini en 1835 y lo elevó a especie Antonio Venturi en 1863.',
       'Es el más raro de los boletos parecidos al hongo en Europa, aunque vive en toda la zona templada.',
       'Se conserva fresco, seco o cocinado como otros boletos comestibles; en el centro de México se vende seco y puede ser caro.'],
  meses=[3, 4, 5, 6, 7, 8, 9, 10, 11], mnota='Primavera y verano con lluvias, y sobre todo en otoño.', wp=['boletus-pinophilus'], rioja=True)

nueva('boletus-reticulatus', cient='Boletus reticulatus', sin=['Boletus aestivalis'], es=['boleto reticulado', 'boleto estival'],
  eu=['udako onddozuri', 'udako onddozuria'], grupo='boleto', clase='sin_datos', cand=True,
  clave='Hongo de verano bajo robles: sombrero pardo claro y a menudo agrietado como una red, pie con retículo blanco marcado y carne que no azulea.',
  mirar=[q('sombrero', 'Pardo, aterciopelado y agrietado', 'Hasta unos 30 cm; cutícula aterciopelada de color pardo, óxido a chocolate, que al secarse se agrieta y deja ver la carne blanca, como una red. Más oscuro y uniforme que el de B. edulis, sin borde blanco o casi.'),
         q('himenio', 'Poros blancos → amarillo → pardo', 'Tubos y poros blancos de joven; amarillo pálido con la edad y pardos al final.'),
         q('pie', 'Retículo blanco muy marcado', 'Hasta unos 12 cm, abultado y con un retículo muy marcado, de blanco a pardo.'),
         q('carne', 'Blanca y firme, con olor agradable', 'Gruesa y blanca; sigue firme aunque amarillee con la edad. Suele estar picada por larvas de insectos. Algo menos firme que en otros boletos.'),
         q('habitat', 'Frondosas, en tiempo cálido y húmedo', 'Bosques de frondosas, sobre todo con roble. Sale desde el principio del verano hasta finales de otoño tras tiempo cálido y húmedo.')],
  conf=[c('boletus-aereus', 'Boletus aereus', 'Muy parecido. Aereus tiene el sombrero más oscuro y el pie más oscuro, con un retículo menos elaborado.'),
        c('boletus-edulis', 'Boletus edulis', 'B. edulis suele tener un borde blanco en el sombrero; en reticulatus ese borde es difuso o falta, y el sombrero es más uniforme y aterciopelado.'),
        c('tylopilus-felleus', 'Tylopilus felleus', 'Poros rosados, retículo oscuro, sabor amargo.', 'media')],
  hab=['robledal', 'frondosas', 'mixto'], habt='Frondosas, sobre todo robles; menos exigente con el árbol que otros boletos del grupo. En la Wikipedia en euskera: con frondosas y coníferas en sitios con mucho musgo, en suelo bien drenado, solo o en grupos.',
  rec=dict(acc='cortar', txt=REC_BOLETO),
  cur=['La describió en 1774 el naturalista alemán Jacob Christian Schäffer. «reticulatus» alude al retículo del pie; algunos autores lo relacionan con la red de grietas del sombrero.',
       'Su carne es algo menos firme que la de otros boletos del grupo y a menudo la atacan las larvas de insectos.',
       'En Borgotaro (Italia) forma parte del «Fungo di Borgotaro», junto con edulis, aereus y pinophilus.'],
  meses=[6, 7, 8, 9, 10, 11], mnota='Desde el principio del verano hasta el final del otoño.', wp=['boletus-reticulatus'], rioja=True)

nueva('imleria-badia', cient='Imleria badia', sin=['Boletus badius', 'Xerocomus badius'], es=['boleto bayo'], eu=['onddo arre', 'onddo uharra'],
  grupo='boleto', clase='sin_datos', cand=True,
  clave='Boleto castaño de bosque de coníferas o mixto cuyos poros amarillos se vuelven azul grisáceo al tocarlos o cortarlos.',
  mirar=[q('sombrero', 'Castaño, algo pegajoso', 'Hasta unos 10 cm (la Wikipedia en euskera da 4–15). Casi esférico de joven y luego aplanado; castaño a pardo oscuro, aterciopelado al principio y algo pegajoso con humedad o con la edad. La cutícula se separa mal de la carne.'),
         q('himenio', 'Poros que azulean', 'Cremas a amarillo pálido, verde-amarillentos u oliva con la edad. Al golpearlos o cortarlos se vuelven azul sucio o gris azulado; se separan fácilmente de la carne.'),
         q('carne', 'Blanquecina, azulea un poco', 'Blanquecina o algo amarilla; bajo la cutícula pardo-rosada. Azulea ligeramente en la unión del sombrero con el pie. El azul desaparece al cocinarla.'),
         q('pie', 'Del color del sombrero, más pálido', '4–9 cm. Parecido al sombrero pero más claro, a veces con un tinte rosado. Con estrías longitudinales tenues, un fino polvillo y una red muy fina solo en la parte alta.'),
         q('habitat', 'Coníferas y bosque mixto', 'Muy común en coníferas, menos en bosques mixtos; suelos ácidos. En las islas británicas, de agosto a noviembre.')],
  conf=[c('boletus-aereus', 'Boletus aereus', 'Su carne no cambia de color, el pie tiene retículo y no azulea.'),
        c(None, 'Gyroporus castaneus', 'También comestible según la Wikipedia en español; tiene el pie cavernoso (hueco por dentro).'),
        ],
  hab=['coniferas', 'mixto'], habt='Sobre todo bosques de coníferas y, menos, mixtos, en suelos ácidos (se adapta bien a ellos). Es micorrícica, pero tiene cierta capacidad de vivir también de materia muerta.',
  rec=dict(acc='cortar', txt='Corte limpio por la base con navaja. La Wikipedia avisa de que puede causar alergia a algunas personas. Deja los ejemplares muy pasados (poros verdes, carne blanda), como aconseja La Rioja.'),
  cur=['Se consideró «el pariente pobre» del hongo (B. edulis), aunque autores como Carluccio lo valoran como comestible de calidad.',
       'La describió Elias Fries en 1818 como variedad de Boletus castaneus; en 1931 pasó a Xerocomus y hoy se coloca en Imleria.',
       'Que azulee no es señal de peligro en esta especie: el azul desaparece al cocinarla. Eso no vale para otros boletos que azulean.'],
  meses=[8, 9, 10, 11], mnota='Islas británicas: agosto–noviembre.', wp=['imleria-badia'], rioja=True)

nueva('suillus-luteus', cient='Suillus luteus', sin=['Boletus luteus'], es=['boleto anillado', 'babosillo'], eu=['pinudi-onddo likin', 'pinudi-onddo likina'],
  grupo='boleto', clase='sin_datos', cand=True,
  clave='Boleto de pinar con sombrero viscoso (baboso) pardo chocolate y anillo colgante. Hay que quitarle la cutícula viscosa.',
  mirar=[q('sombrero', 'Baboso, brillante, cónico', 'De 4–10 cm. Castaño a pardo oscuro, de joven cónico y luego aplanado; viscoso al tacto, liso y brillante incluso en seco. La cutícula se pela con facilidad.'),
         q('himenio', 'Poros diminutos', 'Muy pequeños (unos 3 por mm de joven), amarillos que pasan a oliva o amarillo oscuro. También se pelan de la carne.'),
         q('anillo', 'Anillo membranoso', 'Un velo parcial une el pie con el borde del sombrero; al romperse deja un anillo colgante, blanquecino por arriba y de pardo oscuro a violeta por debajo. Es una de las pocas especies del género Suillus con anillo.'),
         q('pie', 'Con puntitos glandulares', '5–10 cm, pálido y más o menos cilíndrico, con la base a veces hinchada. Por encima del anillo tiene puntitos glandulares; por debajo es de color sucio.'),
         q('habitat', 'Pinares', 'Bajo pinos (silvestre, negro, entre otros). Es una especie «pionera»: aparece en las primeras etapas de un pinar joven.')],
  conf=[c(None, 'Suillus granulatus', 'Los ejemplares maduros se pueden confundir con S. granulatus, también comestible según la Wikipedia en español.'),
        c(None, 'Otros Suillus', 'Varios boletos de pinar tienen el sombrero viscoso. Pocos Suillus tienen anillo: es una de las pistas de S. luteus.')],
  hab=['pinar'], habt='Siempre ligado a pinos (silvestre, negro, laricio, etc.). Coloniza pinares jóvenes y plantaciones: por eso se ha extendido por todo el mundo con los pinos plantados.',
  rec=dict(acc='cortar', txt='Corte limpio por la base. La Wikipedia indica que hay que quitar la cutícula viscosa (pileipellis) antes de usarla; la Wikipedia en euskera añade que, aunque la valora como seta de mesa, puede causar un síndrome de intolerancia, sobre todo si se come poco hecha.'),
  cur=['En Rusia, Ucrania y Polonia es muy apreciada: «maslyata», «maślaki» vienen de una palabra que significa «mantecoso».',
       'En Calabria (Italia) se valoró más que el hongo hasta la década de 1940, cuando el hongo se puso de moda.',
       'Linneo la describió ya en 1753, en «Species Plantarum».'],
  meses=[], mnota=None, wp=['suillus-luteus'], rioja=False)

nueva('leccinum-scabrum', cient='Leccinum scabrum', sin=['Boletus scaber', 'Krombholziella scabra'], es=['boleto del abedul', 'boleto de pie escabroso'], eu=['urki-onddo', 'urki-onddoa'],
  grupo='boleto', clase='sin_datos', cand=True,
  clave='Boleto de abedul con pie fino cubierto de escamitas oscuras (como «granos de pimienta»), poros blanquecinos y carne que se vuelve esponjosa enseguida.',
  mirar=[q('sombrero', 'Pardo claro, liso', '4–10 cm. Pardo o beige, a menudo con el borde más claro; liso, sin pelo, de seco a algo viscoso.'),
         q('himenio', 'Poros blancos → grises', 'Blanquecinos de joven y grises después. En los ejemplares viejos, abultados en el sombrero y hundidos alrededor del pie.'),
         q('pie', 'Esbelto, con escamas oscuras', '5–15 cm, delgado, con escamas blancas y de oscuras a negras (de ahí «escabroso»), más estrecho hacia arriba.'),
         q('carne', 'Esponjosa y acuosa', 'En jóvenes firme, pero enseguida se vuelve esponjosa y empapada, sobre todo si llueve. Al cocinarla se pone negra.'),
         q('esporada', 'Esporada parda', 'Parda.'),
         q('habitat', 'Ligado al abedul', 'Crece asociado a abedules (Betula).')],
  conf=[c(None, 'Otros Leccinum de abedul', 'Varios Leccinum viven bajo abedul y los confunden aficionados y micólogos: L. holopus es más pálido y blanquecino en todas sus partes.', 'media')],
  hab=['abedular', 'parque'], habt='Asociado a abedules, también los plantados en parques y zonas urbanas. En la Wikipedia en inglés: en Norteamérica sale de junio a septiembre.',
  rec=dict(acc='cortar', txt='Corte limpio por la base. Recoge solo ejemplares firmes: enseguida se vuelven esponjosos y retienen agua. Algunas guías lo consideran poco interesante.'),
  cur=['Se consume mucho en Finlandia y Rusia. Se puede cocinar en platos de setas o conservar en salmuera o vinagre, y secar para guardar (Wikipedia en euskera).',
       'El pie de escamas oscuras es su rasgo más fácil de recordar; «scabrum» significa rugoso, áspero.'],
  meses=[], mnota=None, wp=['leccinum-scabrum'], rioja=False)

nueva('boletos-poros-rojos', cient='Neoboletus luridiformis / Suillellus luridus (boletos de poros rojos)', sin=['Boletus erythropus (nombre inválido)', 'Boletus luridus'], es=['boleto cetrino (S. luridus)'], eu=['onddo hankagorri', 'onddo zikin', 'behi-onddo'],
  grupo='boleto', clase='sin_datos', cand=True, nomen='Aquí van juntos los boletos «de poros rojos» que azulean al cortarlos: Neoboletus luridiformis (antes B. erythropus) y Suillellus luridus. La Wikipedia dice de ambos que se comen bien cocinados, pero crudos o poco hechos dan gastroenteritis y se parecen a otros boletos venenosos: se recomienda evitarlos a principiantes.',
  clave='Poros naranja-rojos y carne que azulea al corte: STOP. Son comestibles solo muy cocinados y se parecen a especies peligrosas; sin experto, no.',
  nota='Se tratan como «no tocar» para principiantes. Según Wikipedia son comestibles bien cocinados pero tóxicos crudos o mal cocidos (gastroenteritis), y se parecen a otros boletos de poros rojos venenosos. Con alcohol son peligrosos (Wikipedia en euskera).',
  mirar=[q('himenio', 'Poros naranja-rojos que azulean', 'Amarillos de joven y luego naranja-rojos; al tocarlos o cortarlos se ponen azul-negros. Los tubos amarillo-verdosos azulean enseguida.'),
         q('sombrero', 'Pardo, aterciopelado', 'Hasta 20 cm en N. luridiformis; pardo-bayo, hemisférico y aterciopelado de joven. En S. luridus: amarillo-oliváceo a pardo oliva, con manchas rojizas, naranjas o púrpuras.'),
         q('pie', '¿Con o sin retículo?', 'N. luridiformis: pie amarillo lleno de puntitos rojos, SIN retículo. S. luridus: pie CON retículo, y suele preferir suelos calizos. Esta es la forma de separarlas.'),
         q('carne', 'Azul oscuro al corte', 'La carne se pone azul oscuro al cortarla o golpearla. Poco olor.'),
         q('habitat', 'Frondosas y coníferas', 'Frecuentes en verano y otoño y, a menudo, en los mismos sitios que el hongo (B. edulis).')],
  conf=[c('boletus-satanas', 'Rubroboletus satanas', 'También tiene retículo en el pie, pero el sombrero es muy pálido y blanquecino; es moderadamente venenoso. Con poros rojos y carne que azulea, no coger sin experto.', 'alta'),
        c('boletus-edulis', 'Boletus edulis (grupo)', 'Los poros del hongo son blancos a amarillo oliváceos y su carne no azulea. Poros rojos → no es hongo.', 'media')],
  hab=['frondosas', 'coniferas', 'robledal', 'hayedo', 'castanar'], habt='N. luridiformis: bosques de frondosas o coníferas, a menudo donde sale el hongo. S. luridus: frondosas (roble, abedul, castaño, haya) sobre suelos calizos.',
  rec=dict(acc='dejar', txt='Para un principiante: no se coge. Si algún día los coges con alguien que sepa, que sea con experto al lado y el boleto cocinado mucho tiempo; la Wikipedia advierte que crudos o poco hechos dan gastroenteritis y que algunas personas reaccionan mal incluso cocinados, y que no conviene secarlos.'),
  esp='pardo oliva (N. luridiformis)', sind='Gastroenteritis (náuseas, vómitos, calambres abdominales y diarrea) si se comen crudos o poco cocinados. Se sospecha que S. luridus puede aumentar la sensibilidad al alcohol, como el Coprinopsis atramentaria.', lat='30 min a 2 h (S. luridus, según Wikipedia)', grav='Recuperación completa esperable en 24–48 h si se reponen los líquidos (S. luridus)',
  cur=['«erythropus» viene del griego «pie rojo», por el pie con puntitos rojos de N. luridiformis. Persoon lo describió en 1796.',
       'En Francia, Italia, República Checa y Eslovaquia se come S. luridus, pero algunas guías recomiendan evitarlo del todo.',
       'La Wikipedia en euskera dice que a algunos aficionados no les gusta recogerlos porque creen que todos los boletos de poros rojos son venenosos.'],
  meses=[6, 7, 8, 9, 10, 11], mnota='N. luridiformis: verano y otoño europeos.', wp=['neoboletus-luridiformis', 'suillellus-luridus'], rioja=False)
